-- Restore the exact main definition (the hosted difference is comments only).
create or replace function public.place_order(
  p_items           jsonb,
  p_delivery_method public.delivery_method,
  p_payment_method  public.payment_method,
  p_ship            jsonb
)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id        uuid := auth.uid();
  v_order_id       bigint;
  v_subtotal       numeric(10,2) := 0;
  v_delivery_fee   numeric(10,2);
  v_total          numeric(10,2);
  v_item           jsonb;
  v_product_id     bigint;
  v_qty            integer;
  v_name           text;
  v_price          numeric(10,2);
  v_stock          integer;
  v_active         boolean;
  r                record;
  v_pending_count  integer;
  v_pending_limit  integer;
  v_enabled_methods jsonb;
  v_payment_status public.payment_status;
  v_deadline       timestamptz;
  v_require_approval boolean;
  v_window_hours   integer;
  v_ship_name      text;
  v_ship_phone     text;
  v_ship_alt_phone text;
  v_ship_city      text;
  v_ship_district  text;
  v_ship_address   text;
  v_ship_postal_code text;
  v_ship_floor     text;
  v_ship_apartment text;
  v_ship_landmark  text;
  v_notes          text;
  v_gov_id         smallint;
  v_gov_name       text;
  v_save_address   boolean := false;
begin
  -- 1. Authentication check (AUTH-004)
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Authentication required'
      using errcode = '42501', hint = 'AUTH-004';
  end if;

  -- 2. Rate limiting check (SYS-003)
  perform public.check_rate_limit('place_order', 10, interval '1 minute');

  -- 3. Check customer pending orders limit (ORD-010)
  select coalesce((value #>> '{}')::integer, 3)
    into v_pending_limit
    from public.shop_settings
   where key = 'pending_order_limit';

  select count(*)
    into v_pending_count
    from public.orders
   where user_id = v_user_id
     and status = 'pending';

  if v_pending_count >= coalesce(v_pending_limit, 3) then
    raise exception 'Pending orders limit reached'
      using errcode = '22023', hint = 'ORD-010';
  end if;

  -- 4. Validate cart items presence and cap lines (ORD-001, ORD-013)
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Cart is empty'
      using errcode = '22023', hint = 'ORD-001';
  end if;

  if jsonb_array_length(p_items) > 30 then
    raise exception 'Too many items in order'
      using errcode = '22023', hint = 'ORD-013';
  end if;

  -- 5. Check payment method is enabled in settings (ORD-011)
  select coalesce(value, '["cod", "instapay_qr"]'::jsonb)
    into v_enabled_methods
    from public.shop_settings
   where key = 'payment_methods_enabled';

  if not (v_enabled_methods @> to_jsonb(p_payment_method::text)) then
    raise exception 'Payment method is disabled'
      using errcode = '22023', hint = 'ORD-011';
  end if;

  -- 6. Validate shipping payload
  if p_ship is null or jsonb_typeof(p_ship) <> 'object' then
    raise exception 'Shipping details required'
      using errcode = '22023', hint = 'ORD-012';
  end if;

  v_ship_name        := trim(coalesce(p_ship ->> 'name', ''));
  v_ship_phone       := trim(coalesce(p_ship ->> 'phone', ''));
  v_ship_alt_phone   := nullif(trim(coalesce(p_ship ->> 'alt_phone', '')), '');
  v_ship_city        := nullif(trim(coalesce(p_ship ->> 'city', '')), '');
  v_ship_district    := nullif(trim(coalesce(p_ship ->> 'district', '')), '');
  v_ship_address     := trim(coalesce(p_ship ->> 'address', ''));
  v_ship_postal_code := trim(coalesce(p_ship ->> 'postal_code', ''));
  v_ship_floor       := nullif(trim(coalesce(p_ship ->> 'floor', '')), '');
  v_ship_apartment   := nullif(trim(coalesce(p_ship ->> 'apartment', '')), '');
  v_ship_landmark    := nullif(trim(coalesce(p_ship ->> 'landmark', '')), '');
  v_notes            := nullif(trim(coalesce(p_ship ->> 'notes', '')), '');

  if p_ship ? 'governorate_id' and (p_ship ->> 'governorate_id') ~ '^[0-9]+$' then
    v_gov_id := (p_ship ->> 'governorate_id')::smallint;
  else
    raise exception 'Governorate ID required'
      using errcode = '22023', hint = 'ORD-003';
  end if;

  -- Field length check and required fields (ORD-012)
  if char_length(v_ship_name) = 0 or
     char_length(v_ship_name) > 100 or
     char_length(v_ship_phone) = 0 or
     char_length(v_ship_phone) > 20 or
     (v_ship_alt_phone is not null and char_length(v_ship_alt_phone) > 20) or
     (v_ship_city is not null and char_length(v_ship_city) > 150) or
     (v_ship_district is not null and char_length(v_ship_district) > 150) or
     char_length(v_ship_address) = 0 or
     char_length(v_ship_address) > 150 or
     char_length(v_ship_postal_code) = 0 or
     v_ship_postal_code !~ '^[0-9]{5}$' or
     (v_ship_floor is not null and char_length(v_ship_floor) > 50) or
     (v_ship_apartment is not null and char_length(v_ship_apartment) > 50) or
     (v_ship_landmark is not null and char_length(v_ship_landmark) > 150) or
     (v_notes is not null and char_length(v_notes) > 500) then
    raise exception 'Invalid shipping field length or missing required fields'
      using errcode = '22023', hint = 'ORD-012';
  end if;

  select name_en into v_gov_name from public.governorates where id = v_gov_id;
  if v_gov_name is null then
    raise exception 'Governorate not found'
      using errcode = '22023', hint = 'ORD-003';
  end if;

  -- 7. Delivery fee lookup (ORD-004)
  select fee into v_delivery_fee
    from public.delivery_fees
   where governorate_id = v_gov_id and method = p_delivery_method;

  if v_delivery_fee is null then
    raise exception 'Delivery method unavailable'
      using errcode = '22023', hint = 'ORD-004';
  end if;

  -- 8. Validate each cart item individually for missing fields and per-line cap
  for v_item in select jsonb_array_elements(p_items) loop
    if not (v_item ? 'product_id' and (v_item ->> 'product_id') ~ '^[0-9]+$') then
      raise exception 'Each cart line needs a product_id'
        using errcode = '22023', hint = 'ORD-002';
    end if;

    if not (v_item ? 'quantity' and (v_item ->> 'quantity') ~ '^-?[0-9]+$') then
      raise exception 'Each cart line needs a quantity'
        using errcode = '22023', hint = 'ORD-002';
    end if;

    v_qty := (v_item ->> 'quantity')::integer;
    if v_qty <= 0 or v_qty > 20 then
      raise exception 'Quantity must be between 1 and 20'
        using errcode = '22023', hint = 'ORD-006';
    end if;
  end loop;

  -- 9. Lock products and validate stock/price on aggregated line quantities
  for r in
    select (e ->> 'product_id')::bigint as product_id,
           sum((e ->> 'quantity')::integer)::integer as qty
      from jsonb_array_elements(p_items) e
     group by 1
     order by 1
  loop
    v_product_id := r.product_id;
    v_qty := r.qty;

    select name, final_price, stock_quantity, is_active
      into v_name, v_price, v_stock, v_active
      from public.products
     where id = v_product_id
       for update;

    if v_name is null then
      raise exception 'Product not found'
        using errcode = '22023', hint = 'ORD-008';
    end if;

    if not v_active then
      raise exception 'Product is inactive'
        using errcode = '22023', hint = 'ORD-005';
    end if;

    if v_stock < v_qty then
      raise exception 'Not enough stock for %', v_name
        using errcode = '22023', hint = 'ORD-007', detail = 'left=' || v_stock::text;
    end if;

    v_subtotal := v_subtotal + (v_price * v_qty);
  end loop;

  v_total := v_subtotal + v_delivery_fee;

  -- 10. Payment status & deadline calculation
  if p_payment_method::text = 'cod' then
    v_payment_status := 'unpaid';
    v_deadline := null;
  else
    select coalesce((value #>> '{}')::boolean, true)
      into v_require_approval
      from public.shop_settings
     where key = 'require_order_approval';

    if coalesce(v_require_approval, true) then
      v_payment_status := 'awaiting_approval';
      v_deadline := null;
    else
      v_payment_status := 'awaiting_proof';
      select coalesce((value #>> '{}')::integer, 24)
        into v_window_hours
        from public.shop_settings
       where key = 'payment_window_hours';
      v_deadline := now() + (coalesce(v_window_hours, 24) || ' hours')::interval;
    end if;
  end if;

  -- 11. Optionally update saved profile address
  if p_ship ? 'save_address' and (p_ship ->> 'save_address')::boolean = true then
    update public.profiles
       set phone = v_ship_phone,
           alt_phone = v_ship_alt_phone,
           governorate_id = v_gov_id,
           city = v_ship_city,
           district = v_ship_district,
           address = v_ship_address,
           postal_code = v_ship_postal_code,
           floor = v_ship_floor,
           apartment = v_ship_apartment,
           landmark = v_ship_landmark
     where id = v_user_id;
  end if;

  -- 12. Insert order with immutable shipping snapshot including postal code
  insert into public.orders (
    user_id, status, delivery_method, payment_method, payment_status,
    subtotal, shipping_fee, total,
    ship_name, ship_phone, ship_alt_phone, ship_governorate, ship_city,
    ship_district, ship_address, ship_postal_code, ship_floor, ship_apartment, ship_landmark,
    notes, payment_deadline
  ) values (
    v_user_id, 'pending', p_delivery_method, p_payment_method, v_payment_status,
    v_subtotal, v_delivery_fee, v_total,
    v_ship_name, v_ship_phone, v_ship_alt_phone, v_gov_name, v_ship_city,
    v_ship_district, v_ship_address, v_ship_postal_code, v_ship_floor, v_ship_apartment, v_ship_landmark,
    v_notes, v_deadline
  ) returning id into v_order_id;

  -- 13. Insert merged items and decrement stock with stock reason 'order'
  perform set_config('app.stock_reason', 'order', true);
  perform set_config('app.stock_order_id', v_order_id::text, true);

  for r in
    select (e ->> 'product_id')::bigint as product_id,
           sum((e ->> 'quantity')::integer)::integer as qty
      from jsonb_array_elements(p_items) e
     group by 1
     order by 1
  loop
    v_product_id := r.product_id;
    v_qty := r.qty;

    select name, final_price into v_name, v_price
      from public.products
     where id = v_product_id;

    insert into public.order_items (
      order_id, product_id, product_name, quantity, unit_price
    ) values (
      v_order_id, v_product_id, v_name, v_qty, v_price
    );

    update public.products
       set stock_quantity = stock_quantity - v_qty,
           sold_count     = sold_count + v_qty
     where id = v_product_id;
  end loop;

  return v_order_id;
end;
$$;

-- SOURCE: 20261018090000_postal_legacy_update_guards.sql
-- T-4.08b: NOT VALID checks still apply to every UPDATE. Preserve historical
-- missing data without preventing fulfillment or unrelated profile changes.
-- Fresh databases retain orders.ship_postal_code NOT NULL from T-4.08.
alter table public.orders drop constraint if exists orders_ship_postal_code_not_null;
alter table public.profiles drop constraint if exists profiles_address_postal_code_required;

create or replace function public.guard_order_postal_code()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' then
    if new.ship_postal_code is not distinct from old.ship_postal_code then
      return new;
    end if;
  end if;
  if new.ship_postal_code is null or new.ship_postal_code !~ '^[0-9]{5}$' then
    raise exception 'Postal code required for a new order'
      using errcode = '23514', hint = 'ORD-012';
  end if;
  return new;
end;
$$;
revoke all on function public.guard_order_postal_code() from public, anon, authenticated;
create trigger require_order_postal_code
before insert or update on public.orders
for each row execute function public.guard_order_postal_code();

create or replace function public.guard_profile_postal_code()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  -- Registration and erasure may leave the entire delivery address absent.
  if new.address is null and new.governorate_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if row(new.governorate_id, new.city, new.district, new.address,
           new.floor, new.apartment, new.landmark, new.postal_code)
       is not distinct from
       row(old.governorate_id, old.city, old.district, old.address,
           old.floor, old.apartment, old.landmark, old.postal_code) then
      return new;
    end if;
  end if;
  if new.postal_code is null or new.postal_code !~ '^[0-9]{5}$' then
    raise exception 'Postal code required for a saved address'
      using errcode = '23514', hint = 'ORD-012';
  end if;
  return new;
end;
$$;
revoke all on function public.guard_profile_postal_code() from public, anon, authenticated;
create trigger require_profile_postal_code
before insert or update on public.profiles
for each row execute function public.guard_profile_postal_code();

-- Restore the v2 API's safe AUTH-004 response. The function checks auth.uid()
-- before performing writes; anon still cannot place an order or write tables.
revoke all on function public.place_order(jsonb, public.delivery_method, public.payment_method, jsonb) from public;
grant execute on function public.place_order(jsonb, public.delivery_method, public.payment_method, jsonb) to anon, authenticated;


-- SOURCE: 20261018100000_storefront_content.sql
-- T-3.10c: one audited, public, bilingual content document; payment settings
-- stay separate and private. Empty document preserves existing storefront copy.
insert into public.shop_settings (key, value, is_public)
values ('storefront_content', '{}'::jsonb, true)
on conflict (key) do nothing;

create or replace function public.admin_update_storefront_content(
  p_content jsonb, p_expected_updated_at timestamptz
)
returns timestamptz
language plpgsql
security definer
set search_path = public
as $$
declare
  v_revision timestamptz;
  v_key text;
  v_value jsonb;
  v_text text;
  v_base text;
  v_id bigint;
  v_seen text[];
  v_item jsonb;
  v_text_fields text[] := array[
    'hero_title', 'hero_subtitle', 'hero_caption', 'hero_badge',
    'brand_name', 'tagline', 'copyright', 'announcement',
    'about_title', 'about_body', 'delivery_title', 'delivery_body',
    'returns_title', 'returns_summary', 'returns_body',
    'terms_label', 'terms_body', 'privacy_label', 'privacy_body',
    'returns_label', 'shipping_label', 'shipping_body', 'contact_label', 'contact_body'
  ];
begin
  perform public.require_admin();
  if p_content is null or jsonb_typeof(p_content) <> 'object'
     or octet_length(p_content::text) > 160000 then
    raise exception 'Invalid storefront content' using errcode = '22023', hint = 'ADM-007';
  end if;

  for v_key, v_value in select key, value from jsonb_each(p_content) loop
    v_text := v_value #>> '{}';
    v_base := regexp_replace(v_key, '_(ar|en)$', '');
    if v_key ~ '_(ar|en)$' and v_base = any(v_text_fields) then
      if jsonb_typeof(v_value) <> 'string' or char_length(v_text) >
         (case when v_base like '%_body' then 12000 else 500 end) then
        raise exception 'Invalid localized content' using errcode = '22023', hint = 'ADM-007';
      end if;
    elsif v_key = 'hero_image_path' then
      if jsonb_typeof(v_value) <> 'string' or (v_text <> '' and (
        v_text !~ '^settings/hero-[0-9a-f-]{36}\.(webp|jpg|png)$' or not exists (
          select 1 from storage.objects where bucket_id = 'product-images' and name = v_text
        ))) then
        raise exception 'Invalid hero image' using errcode = '22023', hint = 'ADM-007';
      end if;
    elsif v_key = 'featured_product_id' then
      if v_value <> 'null'::jsonb then
        if jsonb_typeof(v_value) <> 'number' or v_text !~ '^[1-9][0-9]{0,14}$' then
          raise exception 'Invalid featured product' using errcode = '22023', hint = 'ADM-007';
        end if;
        if not exists (select 1 from public.products where id = v_text::bigint and is_active) then
          raise exception 'Featured product unavailable' using errcode = '22023', hint = 'ADM-007';
        end if;
      end if;
    elsif v_key in ('category_ids', 'footer_order') then
      if jsonb_typeof(v_value) <> 'array' then
        raise exception 'Invalid content list' using errcode = '22023', hint = 'ADM-007';
      end if;
      if jsonb_array_length(v_value) > 12 then
        raise exception 'Content list too long' using errcode = '22023', hint = 'ADM-007';
      end if;
      v_seen := array[]::text[];
      for v_item in select value from jsonb_array_elements(v_value) loop
        v_text := v_item #>> '{}';
        if v_text is null or v_text = any(v_seen) then
          raise exception 'Duplicate content item' using errcode = '22023', hint = 'ADM-007';
        end if;
        v_seen := array_append(v_seen, v_text);
        if v_key = 'category_ids' then
          if jsonb_typeof(v_item) <> 'number' or v_text !~ '^[1-9][0-9]{0,14}$' then
            raise exception 'Invalid category' using errcode = '22023', hint = 'ADM-007';
          end if;
          v_id := v_text::bigint;
          if not exists (select 1 from public.categories where id = v_id and is_active) then
            raise exception 'Category unavailable' using errcode = '22023', hint = 'ADM-007';
          end if;
        elsif jsonb_typeof(v_item) <> 'string' or v_text not in ('terms','privacy','returns','shipping','contact') then
          raise exception 'Invalid footer route' using errcode = '22023', hint = 'ADM-007';
        end if;
      end loop;
      if v_key = 'footer_order' and cardinality(v_seen) <> 5 then
        raise exception 'All policy links required' using errcode = '22023', hint = 'ADM-007';
      end if;
    elsif v_key in ('phone', 'whatsapp_url', 'instagram_url', 'tiktok_url') then
      if jsonb_typeof(v_value) <> 'string' or char_length(v_text) > 500 or (v_text <> '' and not (
        (v_key = 'phone' and v_text ~ '^\+?[0-9 ()-]{6,30}$') or
        (v_key = 'whatsapp_url' and v_text ~ '^https://(wa\.me|chat\.whatsapp\.com)/[A-Za-z0-9_/?=&%-]+$') or
        (v_key = 'instagram_url' and v_text ~ '^https://(www\.)?instagram\.com/[A-Za-z0-9_./?=&%-]+$') or
        (v_key = 'tiktok_url' and v_text ~ '^https://(www\.)?tiktok\.com/@[A-Za-z0-9_./?=&%-]+$')
      )) then
        raise exception 'Invalid public contact' using errcode = '22023', hint = 'ADM-007';
      end if;
    else
      raise exception 'Content field not allowed' using errcode = '22023', hint = 'ADM-008';
    end if;
  end loop;
  foreach v_base in array v_text_fields loop
    if (nullif(trim(p_content ->> (v_base || '_ar')), '') is null)
       <> (nullif(trim(p_content ->> (v_base || '_en')), '') is null) then
      raise exception 'Both translations required' using errcode = '22023', hint = 'ADM-007';
    end if;
  end loop;

  select updated_at into v_revision from public.shop_settings
    where key = 'storefront_content' for update;
  -- A stale revision is an expected editing conflict, not a raw database error.
  if v_revision is distinct from p_expected_updated_at then return null; end if;
  update public.shop_settings set value = p_content,
    updated_at = clock_timestamp(), updated_by = auth.uid()
    where key = 'storefront_content' returning updated_at into v_revision;
  return v_revision;
end;
$$;
revoke all on function public.admin_update_storefront_content(jsonb, timestamptz) from public, anon;
grant execute on function public.admin_update_storefront_content(jsonb, timestamptz) to authenticated;


-- SOURCE: 20261018140000_customer_notifications_and_suggestions.sql
-- =====================================================================
-- 20261018140000_customer_notifications_and_suggestions.sql : T-2.10
-- Customer Notifications, Suggestions, and Admin Wishlist Demand View
-- =====================================================================

-- 1. Customer Notifications Table
create table if not exists public.customer_notifications (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null references public.profiles (id) on delete cascade,
  type text not null check (type in ('wishlist_sale', 'order_approved', 'general_sale')),
  title_ar text not null check (char_length(trim(title_ar)) > 0 and char_length(title_ar) <= 120),
  title_en text not null check (char_length(trim(title_en)) > 0 and char_length(title_en) <= 120),
  message_ar text not null check (char_length(trim(message_ar)) > 0 and char_length(message_ar) <= 500),
  message_en text not null check (char_length(trim(message_en)) > 0 and char_length(message_en) <= 500),
  link text check (link is null or char_length(link) <= 255),
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);

create index if not exists customer_notifications_user_idx
  on public.customer_notifications (customer_id, created_at desc);

create index if not exists customer_notifications_unread_idx
  on public.customer_notifications (customer_id, is_read)
  where is_read = false;

alter table public.customer_notifications enable row level security;

drop policy if exists customer_notifications_select on public.customer_notifications;
create policy customer_notifications_select on public.customer_notifications
  for select
  to authenticated
  using (customer_id = auth.uid());

drop policy if exists customer_notifications_update on public.customer_notifications;
create policy customer_notifications_update on public.customer_notifications
  for update
  to authenticated
  using (customer_id = auth.uid())
  with check (customer_id = auth.uid());

drop policy if exists customer_notifications_delete on public.customer_notifications;
create policy customer_notifications_delete on public.customer_notifications
  for delete
  to authenticated
  using (customer_id = auth.uid());

revoke insert on public.customer_notifications from public, anon, authenticated;
grant select, update (is_read), delete on public.customer_notifications to authenticated;

-- Mark all notifications as read for current customer
create or replace function public.mark_all_notifications_read()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501', hint = 'AUTH-001';
  end if;

  update public.customer_notifications
     set is_read = true
   where customer_id = auth.uid()
     and is_read = false;
end;
$$;

revoke all on function public.mark_all_notifications_read() from public, anon;
grant execute on function public.mark_all_notifications_read() to authenticated;

-- 2. Customer Suggestions Table
create table if not exists public.customer_suggestions (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid references public.profiles (id) on delete set null,
  topic text not null check (topic in ('products', 'service', 'delivery', 'website', 'other')),
  message text not null check (char_length(trim(message)) >= 10 and char_length(message) <= 1000),
  status text not null default 'pending' check (status in ('pending', 'reviewed', 'archived')),
  admin_notes text check (admin_notes is null or char_length(admin_notes) <= 500),
  created_at timestamptz not null default now(),
  reviewed_at timestamptz
);

create index if not exists customer_suggestions_created_idx
  on public.customer_suggestions (created_at desc);

create index if not exists customer_suggestions_customer_idx
  on public.customer_suggestions (customer_id, created_at desc);

alter table public.customer_suggestions enable row level security;

drop policy if exists customer_suggestions_select on public.customer_suggestions;
create policy customer_suggestions_select on public.customer_suggestions
  for select
  to authenticated
  using (customer_id = auth.uid() or public.is_admin());

drop policy if exists customer_suggestions_admin_update on public.customer_suggestions;
create policy customer_suggestions_admin_update on public.customer_suggestions
  for update
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

revoke insert, update, delete on public.customer_suggestions from public, anon, authenticated;
grant select on public.customer_suggestions to authenticated;

-- Secure submission RPC for suggestions with rate limiting
create or replace function public.submit_customer_suggestion(
  p_topic text,
  p_message text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid;
  v_recent_count integer;
  v_id uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'Authentication required' using errcode = '42501', hint = 'AUTH-001';
  end if;

  if p_topic is null or p_topic not in ('products', 'service', 'delivery', 'website', 'other') then
    raise exception 'Invalid suggestion topic' using errcode = '22023', hint = 'SUG-002';
  end if;

  if p_message is null or char_length(trim(p_message)) < 10 or char_length(p_message) > 1000 then
    raise exception 'Suggestion message must be between 10 and 1000 characters' using errcode = '22023', hint = 'SUG-003';
  end if;

  -- Rate limit: maximum 5 suggestions per customer in the last hour
  select count(*)
    into v_recent_count
    from public.customer_suggestions
   where customer_id = v_uid
     and created_at > now() - interval '1 hour';

  if v_recent_count >= 5 then
    raise exception 'Too many suggestions submitted. Please try again later.'
      using errcode = '22023', hint = 'SUG-001';
  end if;

  insert into public.customer_suggestions (
    customer_id,
    topic,
    message
  ) values (
    v_uid,
    p_topic,
    trim(p_message)
  )
  returning id into v_id;

  return v_id;
end;
$$;

revoke all on function public.submit_customer_suggestion(text, text) from public, anon;
grant execute on function public.submit_customer_suggestion(text, text) to authenticated;

-- Admin review RPC for suggestions
create or replace function public.admin_review_suggestion(
  p_id uuid,
  p_status text,
  p_notes text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_old_status text;
begin
  perform public.require_admin();

  if p_status is null or p_status not in ('pending', 'reviewed', 'archived') then
    raise exception 'Invalid suggestion status' using errcode = '22023', hint = 'ADM-007';
  end if;

  if p_notes is not null and char_length(p_notes) > 500 then
    raise exception 'Admin notes exceed 500 characters' using errcode = '22023', hint = 'ADM-007';
  end if;

  select status into v_old_status
    from public.customer_suggestions
   where id = p_id;

  if v_old_status is null then
    raise exception 'Suggestion not found' using errcode = 'P0002', hint = 'SUG-004';
  end if;

  update public.customer_suggestions
     set status = p_status,
         admin_notes = p_notes,
         reviewed_at = case when p_status <> 'pending' then now() else null end
   where id = p_id;

  perform public.audit_event(
    'SUGGESTION_REVIEW',
    'customer_suggestions',
    p_id::text,
    jsonb_build_object('status', v_old_status),
    jsonb_build_object('status', p_status, 'notes', p_notes)
  );
end;
$$;

revoke all on function public.admin_review_suggestion(uuid, text, text) from public, anon;
grant execute on function public.admin_review_suggestion(uuid, text, text) to authenticated;

-- 3. Automatic Notifications: Order Approval Trigger
create or replace function public.notify_on_order_approved()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.user_id is not null and
     new.payment_status = 'awaiting_proof' and
     (old.payment_status is distinct from new.payment_status) then
    insert into public.customer_notifications (
      customer_id,
      type,
      title_ar,
      title_en,
      message_ar,
      message_en,
      link
    ) values (
      new.user_id,
      'order_approved',
      'تمت الموافقة على طلبك',
      'Your order has been approved',
      'تمت الموافقة على طلبك #' || new.id || '. يمكنك الآن تأكيد الدفع.',
      'Your order #' || new.id || ' has been approved. You can now submit payment proof.',
      '/pay/' || new.id
    );
  end if;
  return new;
end;
$$;

drop trigger if exists trg_notify_order_approved on public.orders;
create trigger trg_notify_order_approved
  after update of payment_status on public.orders
  for each row
  execute function public.notify_on_order_approved();

-- 4. Automatic Notifications: Wishlist Sale Trigger
create or replace function public.notify_on_wishlist_sale()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.is_active = true and
     new.discount_percent > 0 and
     (old.discount_percent is null or new.discount_percent > old.discount_percent) then
    insert into public.customer_notifications (
      customer_id,
      type,
      title_ar,
      title_en,
      message_ar,
      message_en,
      link
    )
    select
      f.user_id,
      'wishlist_sale',
      'عرض على منتج في مفضلتك',
      'Sale on wishlist item',
      'أصبح المنتج "' || coalesce(new.name_ar, new.name) || '" متوفرًا بخصم ' || new.discount_percent || '%!',
      'The product "' || coalesce(new.name, new.name_ar) || '" is now on sale with ' || new.discount_percent || '% off!',
      '/products/' || new.id
    from public.favorites f
    where f.product_id = new.id;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_notify_wishlist_sale on public.products;
create trigger trg_notify_wishlist_sale
  after update of discount_percent on public.products
  for each row
  execute function public.notify_on_wishlist_sale();

-- 5. Admin Broadcast Sale Notification RPC
create or replace function public.admin_broadcast_sale_notification(
  p_title_ar text,
  p_title_en text,
  p_message_ar text,
  p_message_en text,
  p_link text default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  perform public.require_admin();

  if p_title_ar is null or char_length(trim(p_title_ar)) = 0 or char_length(p_title_ar) > 120 or
     p_title_en is null or char_length(trim(p_title_en)) = 0 or char_length(p_title_en) > 120 or
     p_message_ar is null or char_length(trim(p_message_ar)) = 0 or char_length(p_message_ar) > 500 or
     p_message_en is null or char_length(trim(p_message_en)) = 0 or char_length(p_message_en) > 500 then
    raise exception 'Invalid notification payload' using errcode = '22023', hint = 'ADM-007';
  end if;

  if p_link is not null and char_length(p_link) > 255 then
    raise exception 'Notification link too long' using errcode = '22023', hint = 'ADM-007';
  end if;

  insert into public.customer_notifications (
    customer_id,
    type,
    title_ar,
    title_en,
    message_ar,
    message_en,
    link
  )
  select
    p.id,
    'general_sale',
    trim(p_title_ar),
    trim(p_title_en),
    trim(p_message_ar),
    trim(p_message_en),
    p_link
  from public.profiles p;

  get diagnostics v_count = row_count;

  perform public.audit_event(
    'BROADCAST_SALE_NOTIFICATION',
    'customer_notifications',
    'broadcast',
    null,
    jsonb_build_object('recipient_count', v_count, 'title_en', trim(p_title_en))
  );

  return v_count;
end;
$$;

revoke all on function public.admin_broadcast_sale_notification(text, text, text, text, text) from public, anon;
grant execute on function public.admin_broadcast_sale_notification(text, text, text, text, text) to authenticated;

-- 6. Admin Wishlist Demand Reporting RPC
create or replace function public.admin_get_wishlist_demand()
returns table (
  product_id bigint,
  product_name text,
  product_name_ar text,
  price numeric,
  discount_percent smallint,
  final_price numeric,
  stock_quantity integer,
  is_active boolean,
  image_url text,
  wishlist_count bigint
)
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.require_admin();

  return query
  select
    p.id as product_id,
    p.name as product_name,
    p.name_ar as product_name_ar,
    p.price,
    p.discount_percent,
    p.final_price,
    p.stock_quantity,
    p.is_active,
    p.image_url,
    count(f.user_id) as wishlist_count
  from public.products p
  inner join public.favorites f on f.product_id = p.id
  group by p.id, p.name, p.name_ar, p.price, p.discount_percent, p.final_price, p.stock_quantity, p.is_active, p.image_url
  order by wishlist_count desc, p.id desc;
end;
$$;

revoke all on function public.admin_get_wishlist_demand() from public, anon;
grant execute on function public.admin_get_wishlist_demand() to authenticated;

-- 7. Update Customer Anonymization to Include Notifications and Suggestions
create or replace function public.admin_anonymize_customer(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_target_role public.user_role;
  v_orders_count integer;
begin
  -- 1. Enforce admin role and AAL2 step-up
  perform public.require_admin();

  -- 2. Validate input and ensure profile exists
  if p_user_id is null then
    raise exception 'Customer user ID is required'
      using errcode = '22023', hint = 'ADM-007';
  end if;

  select role into v_target_role
    from public.profiles
   where id = p_user_id;

  if not found then
    raise exception 'Customer profile not found'
      using errcode = 'P0002', hint = 'ORD-009';
  end if;

  if v_target_role = 'admin' then
    raise exception 'Cannot anonymize an administrator account'
      using errcode = '42501', hint = 'ADM-001';
  end if;

  -- 3. Count customer orders for audit metadata
  select count(*) into v_orders_count
    from public.orders
   where user_id = p_user_id;

  -- 4. Anonymize profile personal data
  update public.profiles
     set full_name = 'عميل مجهول',
         phone = null,
         alt_phone = null,
         governorate_id = null,
         city = null,
         district = null,
         address = null,
         postal_code = null,
         floor = null,
         apartment = null,
         landmark = null
   where id = p_user_id;

  -- 5. Anonymize personal delivery and contact info on all orders belonging to user
  update public.orders
     set ship_name = 'عميل مجهول',
         ship_phone = '00000000000',
         ship_alt_phone = null,
         ship_city = null,
         ship_district = null,
         ship_address = '[محذوف]',
         ship_floor = null,
         ship_apartment = null,
         ship_landmark = null,
         notes = null,
         payment_reference = null,
         payment_proof_path = null
   where user_id = p_user_id;

  -- 6. Delete personal customer favorites
  delete from public.favorites
   where user_id = p_user_id;

  -- 7. Delete personal customer notifications
  delete from public.customer_notifications
   where customer_id = p_user_id;

  -- 8. Disassociate customer suggestions
  update public.customer_suggestions
     set customer_id = null
   where customer_id = p_user_id;

  -- 9. Audit the anonymization action (without logging personal details)
  perform public.audit_event(
    'CUSTOMER_ANONYMIZE',
    'profiles',
    p_user_id::text,
    jsonb_build_object('anonymized', false, 'orders_count', v_orders_count),
    jsonb_build_object('anonymized', true, 'orders_count', v_orders_count)
  );
end;
$$;

revoke all on function public.admin_anonymize_customer(uuid) from public, anon;
grant execute on function public.admin_anonymize_customer(uuid) to authenticated;


-- SOURCE: 20261018160000_customer_profile_photo.sql
-- =====================================================================
-- 20261018160000_customer_profile_photo.sql
-- Customer Profile Photo (T-2.11)
-- Implements user-owned validated avatar storage, replacement cleanup,
-- folder security triggers, RLS policies, and GDPR erasure support.
-- =====================================================================

-- 1. Add avatar_url column to profiles
alter table public.profiles
  add column if not exists avatar_url text;

-- 2. Constraints on profiles.avatar_url
alter table public.profiles
  drop constraint if exists profiles_avatar_url_length;
alter table public.profiles
  add constraint profiles_avatar_url_length
  check (avatar_url is null or char_length(avatar_url) <= 300);

alter table public.profiles
  drop constraint if exists profiles_avatar_url_path;
alter table public.profiles
  add constraint profiles_avatar_url_path
  check (avatar_url is null or avatar_url ~ '^[0-9a-fA-F-]{36}/[A-Za-z0-9/_-]+\.(webp|jpg|jpeg|png)$');

-- 3. Grant column update permissions to authenticated role
grant update (avatar_url) on public.profiles to authenticated;

-- 4. User folder integrity trigger:
-- Ensures avatar_url belongs to the profile's own user ID folder
create or replace function public.validate_profile_avatar()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.avatar_url is not null then
    if split_part(new.avatar_url, '/', 1) <> new.id::text then
      raise exception 'Avatar path must match user ID: %', new.id
        using errcode = '23514', hint = 'SEC-001';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_validate_profile_avatar on public.profiles;
create trigger trg_validate_profile_avatar
  before insert or update on public.profiles
  for each row
  execute function public.validate_profile_avatar();

-- 5. Storage bucket 'avatars' with 2 MB limit and allowed image MIME types
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'avatars',
  'avatars',
  true,
  2097152, -- 2 MB limit
  array['image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update
  set public = true,
      file_size_limit = 2097152,
      allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp'];

-- 6. Storage RLS policies for 'avatars' bucket
-- 6a. Public read access
drop policy if exists "public read avatars" on storage.objects;
create policy "public read avatars" on storage.objects
  for select
  using (bucket_id = 'avatars');

-- 6b. User-owned upload (INSERT)
drop policy if exists "user upload avatar" on storage.objects;
create policy "user upload avatar" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

-- 6c. User-owned update (UPDATE)
drop policy if exists "user update avatar" on storage.objects;
create policy "user update avatar" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  )
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

-- 6d. User delete avatar (DELETE) - owner or admin
drop policy if exists "user delete avatar" on storage.objects;
create policy "user delete avatar" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'avatars'
    and (
      (storage.foldername(name))[1] = (select auth.uid())::text
      or public.is_admin()
    )
  );

-- 7. Automated replacement cleanup trigger:
-- When a user changes or removes their avatar_url, purge the old storage object
create or replace function public.cleanup_old_avatar()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.avatar_url is not null and (new.avatar_url is null or new.avatar_url <> old.avatar_url) then
    delete from storage.objects
     where bucket_id = 'avatars'
       and name = old.avatar_url;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_cleanup_old_avatar on public.profiles;
create trigger trg_cleanup_old_avatar
  after update on public.profiles
  for each row
  execute function public.cleanup_old_avatar();

-- 8. Automated profile deletion cleanup trigger
create or replace function public.cleanup_deleted_profile_avatar()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.avatar_url is not null then
    delete from storage.objects
     where bucket_id = 'avatars'
       and name = old.avatar_url;
  end if;
  return old;
end;
$$;

drop trigger if exists trg_cleanup_deleted_profile_avatar on public.profiles;
create trigger trg_cleanup_deleted_profile_avatar
  after delete on public.profiles
  for each row
  execute function public.cleanup_deleted_profile_avatar();

-- 9. Update admin_anonymize_customer to clear avatar_url and purge storage objects
create or replace function public.admin_anonymize_customer(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_target_role public.user_role;
  v_orders_count integer;
begin
  -- 1. Enforce admin role and AAL2 step-up
  perform public.require_admin();

  -- 2. Validate input and ensure profile exists
  if p_user_id is null then
    raise exception 'Customer user ID is required'
      using errcode = '22023', hint = 'ADM-007';
  end if;

  select role into v_target_role
    from public.profiles
   where id = p_user_id;

  if not found then
    raise exception 'Customer profile not found'
      using errcode = 'P0002', hint = 'ORD-009';
  end if;

  if v_target_role = 'admin' then
    raise exception 'Cannot anonymize an administrator account'
      using errcode = '42501', hint = 'ADM-001';
  end if;

  -- 3. Count customer orders for audit metadata
  select count(*) into v_orders_count
    from public.orders
   where user_id = p_user_id;

  -- 4. Anonymize profile personal data
  update public.profiles
     set full_name = 'عميل مجهول',
         phone = null,
         alt_phone = null,
         email = null,
         postal_code = null,
         avatar_url = null,
         governorate_id = null,
         city = null,
         address = null,
         district = null,
         floor = null,
         apartment = null,
         landmark = null
   where id = p_user_id;

  -- 5. Delete customer avatar from storage
  delete from storage.objects
   where bucket_id = 'avatars'
     and (storage.foldername(name))[1] = p_user_id::text;

  -- 6. Anonymize personal delivery and contact info on all orders belonging to user
  update public.orders
     set ship_name = 'عميل مجهول',
         ship_phone = '00000000000',
         ship_address = 'عنوان ممسوح',
         ship_city = 'مدينة ممسوحة',
         ship_postal_code = '00000',
         ship_district = null,
         ship_floor = null,
         ship_apartment = null,
         ship_landmark = null
   where user_id = p_user_id;

  -- 7. Audit log the anonymization action with metadata
  insert into public.audit_log (
    actor,
    actor_role,
    action,
    entity,
    entity_id,
    old,
    new
  ) values (
    auth.uid(),
    'admin',
    'anonymize_customer',
    'profiles',
    p_user_id::text,
    jsonb_build_object('orders_count', v_orders_count),
    jsonb_build_object('anonymized', true, 'avatar_purged', true)
  );
end;
$$;

revoke all on function public.admin_anonymize_customer(uuid) from public, anon;
grant execute on function public.admin_anonymize_customer(uuid) to authenticated;


-- SOURCE: 20261018170000_instapay_recipient_and_qr.sql
-- =====================================================================
-- 20261018170000_instapay_recipient_and_qr.sql : T-5.14 Verify owner
-- InstaPay recipient and QR.
-- Configures verified owner recipient alaa.ahm9624@instapay in shop_settings,
-- ensures private delivery via get_payment_instructions, and supports both
-- handle and instapay_handle return keys.
-- =====================================================================

-- 1. Ensure approved owner recipient is configured in shop_settings
update public.shop_settings
   set value = '"alaa.ahm9624@instapay"'::jsonb
 where key = 'instapay_handle'
   and (value = '""'::jsonb or value is null or value = '""' or value = 'null'::jsonb);

-- 2. Re-assert privacy of InstaPay payment instruction settings
update public.shop_settings
   set is_public = false
 where key in ('instapay_handle', 'instapay_qr_path');

-- 3. Replace get_payment_instructions to return normalized handle keys and owner fallback
create or replace function public.get_payment_instructions(p_order_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid            uuid := auth.uid();
  v_order_uid      uuid;
  v_status         public.payment_status;
  v_total          numeric(10,2);
  v_deadline       timestamptz;
  v_qr_path        text;
  v_handle         text;
begin
  if v_uid is null then
    raise exception 'Authentication required'
      using errcode = '42501', hint = 'AUTH-004';
  end if;

  select user_id, payment_status, total, payment_deadline
    into v_order_uid, v_status, v_total, v_deadline
    from public.orders
   where id = p_order_id;

  if v_order_uid is null or v_order_uid <> v_uid then
    raise exception 'Not owner of order'
      using errcode = '42501', hint = 'ORD-009';
  end if;

  if v_status::text = 'awaiting_approval' then
    raise exception 'Order is awaiting store approval'
      using errcode = '22023', hint = 'PAY-007';
  end if;

  if v_status::text not in ('awaiting_proof', 'under_review', 'rejected') then
    raise exception 'Wrong payment status for instructions'
      using errcode = '22023', hint = 'PAY-004';
  end if;

  select value #>> '{}' into v_qr_path from public.shop_settings where key = 'instapay_qr_path';
  select value #>> '{}' into v_handle from public.shop_settings where key = 'instapay_handle';

  return jsonb_build_object(
    'qr_path', coalesce(v_qr_path, 'settings/instapay-qr-default.png'),
    'handle', coalesce(nullif(v_handle, ''), 'alaa.ahm9624@instapay'),
    'instapay_handle', coalesce(nullif(v_handle, ''), 'alaa.ahm9624@instapay'),
    'amount', v_total,
    'deadline', v_deadline
  );
end;
$$;

revoke all on function public.get_payment_instructions(bigint) from public, anon;
grant execute on function public.get_payment_instructions(bigint) to authenticated;


-- SOURCE: 20261018180000_occasion_reminders.sql
-- Migration: 20261018180000_occasion_reminders.sql
-- Description: Task T-9.14: Upcoming occasion reminders for admins
-- Provides AAL2-only API for calendar occasions, in-app deduplicated admin reminders,
